/**
 * Client-credentials tokens for service-to-service calls (registration id "svc", e.g. client svc-core).
 * Only created when the outbox relay is enabled, so services without a "svc" registration are unaffected.
 * Tokens are cached and refreshed by Spring Security until shortly before expiry.
 */
@Configuration
@ConditionalOnProperty(prefix = "turfclub.outbox", name = "relay-enabled", havingValue = "true")
public class ServiceClientConfiguration {

    public static final String REGISTRATION_ID = "svc";

    @Bean
    public ServiceTokenProvider serviceTokenProvider(ClientRegistrationRepository registrations,
                                                     OAuth2AuthorizedClientService clientService) {
        AuthorizedClientServiceOAuth2AuthorizedClientManager manager =
                new AuthorizedClientServiceOAuth2AuthorizedClientManager(registrations, clientService);
        manager.setAuthorizedClientProvider(OAuth2AuthorizedClientProviderBuilder.builder().clientCredentials().build());
        return () -> {
            OAuth2AuthorizedClient client = manager.authorize(
                    OAuth2AuthorizeRequest.withClientRegistrationId(REGISTRATION_ID).principal("turfclub-service").build());
            if (client == null) {
                throw new IllegalStateException("Keycloak did not issue a client-credentials token for registration '"
                        + REGISTRATION_ID + "'");
            }
            return client.getAccessToken().getTokenValue();
        };
    }

    /** Supplies a bearer token for outbound calls. */
    @FunctionalInterface
    public interface ServiceTokenProvider {
        String token();
    }
}
